cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Check if there's any warranty referencing this product
const w = db.prepare(\"SELECT * FROM warranties WHERE product_id = 'PROD-73FAB4'\").all();
console.log('Warranties by product:', JSON.stringify(w, null, 2));
// Also check all warranties
const allW = db.prepare('SELECT COUNT(*) as cnt FROM warranties').get();
console.log('Total warranties:', allW.cnt);
const sample = db.prepare('SELECT * FROM warranties LIMIT 5').all();
console.log('Sample:', JSON.stringify(sample, null, 2));
"

cd /workspace && node -e "
